function initAccordion(){document.querySelectorAll(".accordion__titular").forEach(function(c){c.addEventListener("click",function(){const c=this.parentElement;if(c.classList.contains("active")){c.classList.remove("active");const o=this.querySelector(".accordion__icon");return void(o&&o.classList.remove("accordion__icon--active"))}document.querySelectorAll(".accordion__section").forEach(function(c){c.classList.remove("active")}),document.querySelectorAll(".accordion__icon").forEach(function(c){c.classList.remove("accordion__icon--active")}),c.classList.add("active");const o=this.querySelector(".accordion__icon");o&&o.classList.add("accordion__icon--active")})})}"loading"===document.readyState?document.addEventListener("DOMContentLoaded",initAccordion,{once:!0}):initAccordion();